/// ⚠️⚠️ **「확정」이 아니다** — 사용자: 「고른 거는 **확정이 아니고 거기서 조금 더
///   다듬을 거야**」. 그래서 **목록에서 지우지 않고 여기서 거른다**:
///   캐릭터 장에는 셋이 그대로 서 있어 **언제든 되돌아갈 수 있다.**
///   ⇒ 광주 절은 「확정」이고 이 둘은 「다듬는 중」이다. 그 차이가 화면에도 있다.
// ⭐ **독침은 확정돼 캐릭터 장으로 갔다**(2026-08-23 사용자: 「독표창은 시안 확정.
//   독 쪽으로 이동」) ⇒ **고르기에서 뺀다.** 「옮겼으면 고르기에서 지워야지」가
//   이 사이클의 고정 실패라 넣기와 빼기를 **같이** 한다.
// ⚠️ **독가스 둘(`PZgasBombA`·`PZgasBombD`)을 뺐다** — 확정돼 독 장으로 갔다.
//   「옮겼으면 고르기에서 지워야지」가 이 사이클의 고정 실패라 **넣기와 빼기를 같이** 한다.
const PZPICK={PZnumbHalt:1,PZnumbShift:1};
for(const[charId,pickId,LIST]of PZMOUNT)
  for(const[id,onlyPicked]of[[charId,0],[pickId,1]]){
    const H=document.getElementById(id);if(!H)continue;
    for(const[k,nm,ds,lv]of LIST){
      if(onlyPicked&&!PZPICK[k])continue;
      // ⚠️ `lv` 를 안 주면 L5 다(스킬 격자의 규약). 성장 줄만 1~5 를 준다.
      tile(H,FX,k,nm,"",ds,236,236,undefined,lv||5);}}
